import {progressSummary} from './progress.js';
import {matchingFeed} from './matching.js';
const skippedQuestions=new Map();
import {editorMarkup,mountEditor} from './editor.js';
import {migrateTree} from './graph-model.js';
import {TYPES,clone,initialState,edges,validateTree,evaluate,mutual,questionsFor} from './engine.js';
const KEY='cupid-lab-v1';let state=initialState();try{const raw=localStorage.getItem(KEY),saved=JSON.parse(raw);if(saved?.profiles){if(saved.profiles.some(p=>p.tree?.nodes?.some(n=>n.items))&&!localStorage.getItem('cupid-before-blocks'))localStorage.setItem('cupid-before-blocks',raw);saved.profiles.forEach(p=>migrateTree(p.tree));}if(saved?.version===1&&saved.profiles?.length===2&&saved.profiles.every(p=>!validateTree(p.tree,{allowUnconnected:true}).length&&p.answers&&p.attraction))state=saved;}catch{}
let tab='tree',mode='visual',selected=state.profiles.find(p=>p.id===state.active)?.tree.start||'kind',zoom=1,showTrace=false;
const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=()=>state.profiles.find(p=>p.id===state.active)||state.profiles[0];const other=()=>state.profiles.find(p=>p.id!==current().id);
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',3400)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Browser storage is full or unavailable. Export your tree to keep it.')}}
const icons={tree:'M4 4h6v5H4z M14 15h6v5h-6z M4 15h6v5H4z M7 9v3h10v3 M7 12v3',profile:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M4 21v-2a8 8 0 0 1 16 0v2',appearance:'M12 20S3 14 3 8a5 5 0 0 1 9-3 5 5 0 0 1 9 3c0 6-9 12-9 12Z',questions:'M4 4h16v12H9l-5 4z M8 8h8 M8 12h5',simulate:'m8 4 12 8-12 8z'};
function render(){const p=current();app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">⌘</span> cupid <small>LAB</small></div><div><div class="eyebrow" style="padding:0 12px;margin-bottom:12px">Your workspace</div><nav class="nav">${[['tree','My tree'],['profile','My profile'],['appearance','Attraction'],['questions','Questions'],['simulate','Matches']].map(([id,label])=>`<button data-tab="${id}" class="${tab===id?'active':''}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[id]}"/></svg>${label}</button>`).join('')}</nav></div><div class="sidefoot"><strong>A little logic. A little chemistry.</strong><br><br>Personal proof of concept<br>Changes stay in this browser.</div></aside><main class="workspace"><header class="topbar"><div class="context">Compatibility lab <span>/</span> <span>A space to figure out your type</span></div><div class="person-switch"><div class="avatar">${esc(p.name.slice(0,1))}</div><select id="person" aria-label="Switch demo person">${state.profiles.map(x=>`<option value="${x.id}" ${p.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></header><div class="page">${tab==='tree'?treePage():tab==='profile'?profilePage():tab==='appearance'?appearancePage():tab==='questions'?questionsPage():simulationPage()}</div></main></div>`;bind();if(tab==='tree')mountEditor(current().tree,tree=>{current().tree=tree;save();render();},toast);}
function title(name,desc,actions=''){return `<div class="pagehead"><div><h1>${name}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function treePage(){return title('Your type, in your own terms.','Questions supply answers. Blocks combine them into your rules.', '<button data-action="export">Export tree</button><button class="primary" data-action="simulate">View matches</button>')+editorMarkup(current().tree,current().id);}
function input(label,name,value,type='text'){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'step="1"':''}></label>`}
function profilePage(){const p=current();return `${title('The person behind the paths.','Public details and private context, in one place.')}<div class="notice">Two-person demo · the person switcher lets you edit both sides. “Private” fields are excluded from the match reveal, but everything is stored together in this browser. Use sample information.</div><form id="profile-form"><div class="cards"><section class="card"><div class="profile-heading"><div class="avatar">${esc(p.name.slice(0,1))}</div><div><h2>Public profile</h2><span class="small muted">Revealed after a mutual match</span></div></div>${input('Name','name',p.name)}<label class="field"><span>A little about you</span><textarea name="bio" rows="4">${esc(p.bio)}</textarea></label><label class="field"><span>Public hobbies</span><textarea name="publicHobbies" rows="4">${esc(p.publicHobbies)}</textarea><small class="hint">Separate interests with commas.</small></label><label class="field"><span>Photo for the attraction screen</span><input id="photo-upload" type="file" accept="image/png,image/jpeg,image/webp"><small class="hint">Saved on this device only. Choose a photo under 2 MB.</small></label>${p.photo?`<div class="portrait" style="height:200px"><img src="${esc(p.photo)}" alt="Your profile photo"></div><button type="button" data-action="remove-photo">Remove photo</button>`:''}</section><section class="card"><span class="badge rose">MATCHING ONLY</span><h2 style="margin-top:17px">Your private context</h2><p class="muted small">Interests you want considered without adding them to your public profile.</p><label class="field"><span>Private hobbies</span><textarea name="privateHobbies" rows="5">${esc(p.privateHobbies)}</textarea></label><div class="note-card"><h3>Let the overlap do the talking.</h3><p>A hobby condition compares both lists. A match can see that compatible interests exist, without seeing the hidden hobby names.</p></div><p class="privacy">Demo matching recognizes exact names and a small related-interest dictionary, including LoL / League of Legends and hiking / trail walking. It is not an LLM and can miss reasonable overlap.</p></section></div><div class="export-row"><button type="submit" class="primary">Save profile</button><button type="button" data-action="simulate">Try the match lab</button></div></form>`}
function appearancePage(){const p=current(),q=other(),rating=p.attraction[q.id];return `${title('A little chemistry.','Keep your visual preference separate from personality.')}<div class="split"><section class="card"><span class="eyebrow">Appearance only</span><div class="portrait">${q.photo?`<img src="${esc(q.photo)}" alt="${esc(q.name)}’s profile photo">`:`<p>No photo yet.<br>Add a photo from ${esc(q.name)}’s profile using the person switcher.</p>`}</div><h2>${esc(q.name)}</h2><div class="ratingline"><span class="small muted">Your private attraction rating</span><span class="score" id="rating-display">${rating??'—'}<span class="small muted"> / 10</span></span></div><label class="field"><span>Rate visual attraction</span><input id="attraction-range" type="range" min="1" max="10" value="${rating??5}" aria-label="Visual attraction score"></label><div class="range-labels"><span>Not my type</span><span>Very much my type</span></div><div class="choices" style="margin-top:22px"><button data-action="pass-attraction" class="${rating<6?'chosen':''}">Pass</button><button data-action="like-attraction" class="${rating>=6?'chosen':''}">Interested</button><button class="ghost" data-action="clear-attraction">Clear</button></div></section><section class="card"><h2>Two independent signals.</h2><p class="small muted">This demo treats a rating of 6–10 as interest. Both people must be interested and reach a compatible outcome in each other’s trees before their public profiles are revealed.</p><hr class="sectionline"><h3>Your tree can use this score, too.</h3><p class="small muted" style="margin-top:10px">To try your fast-track idea, add a scalar node in the tree editor and set its value source to “My appearance rating.” Route 8–10 around any steps you choose.</p><button data-action="tree">Open my tree</button><div class="notice" style="margin-top:24px;margin-bottom:0">Seeded ratings are sample data for testing. No rating is shared with the other person.</div></section></div>`}
function questionControl(q,p){const v=p.answers[q.key];if(q.type==='boolean')return `<div class="choices"><button data-answer="${esc(q.key)}" data-value="true" class="${v===true?'chosen':''}">Yes</button><button data-answer="${esc(q.key)}" data-value="false" class="${v===false?'chosen':''}">No</button></div>`;if(q.type==='category')return `<div class="choices">${q.options.map(o=>`<button data-answer="${esc(q.key)}" data-category="${esc(o.value)}" class="${v===o.value?'chosen':''}">${esc(o.value)}</button>`).join('')}</div>`;return `<label class="field"><span>Choose a whole number from ${q.min} to ${q.max}</span><select data-scalar="${esc(q.key)}"><option value="">Not answered</option>${Array.from({length:q.max-q.min+1},(_,i)=>q.min+i).map(i=>`<option value="${i}" ${v===i?'selected':''}>${i}</option>`).join('')}</select></label>`}
function anonymousQuestions(){
 const p=current(),skipped=skippedQuestions.get(p.id)||new Set(),feed=matchingFeed(state.profiles,p,skipped),q=feed.questions[0];
 return '<section class="card" style="max-width:650px">'+(q?'<h2>'+esc(q.label)+'</h2>'+questionControl(q,p)+'<button class="ghost" data-skip-question="'+esc(q.key)+'">Skip for now</button>':'<p>No questions available right now.</p>')+'</section>';
}
function questionsPage(){return title('A few things about you.','Answer at your own pace.')+anonymousQuestions();}
function simulationPage(){const stats=progressSummary(state.profiles,current());return title('Your progress.','Fill out questions to progress through other people’s trees!')+'<div class="card" style="margin-bottom:20px"><p>The highest number of nodes passed through by someone else is <strong>'+stats.incoming.passed+'/'+stats.incoming.total+'</strong></p><p>Your highest number of nodes passed through someone else’s tree is <strong>'+stats.outgoing.passed+'/'+stats.outgoing.total+'</strong></p><small class="muted">Decision nodes only. The total follows the chosen path plus its longest remaining compatible route.</small></div>'+anonymousQuestions();}
function bind(){document.querySelectorAll('[data-skip-question]').forEach(b=>b.onclick=()=>{const p=current(),skipped=skippedQuestions.get(p.id)||new Set();skipped.add(b.dataset.skipQuestion);skippedQuestions.set(p.id,skipped);render();});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});document.querySelector('#person').onchange=e=>{state.active=e.target.value;selected=current().tree.start;save();render()};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelector('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);if(!String(f.get('name')).trim())return toast('Add a name first.');for(const key of ['name','bio','publicHobbies','privateHobbies'])current()[key]=String(f.get(key)).trim();save();render();toast('Profile saved on this device.');});
document.querySelector('#photo-upload')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('Choose a PNG, JPG, or WebP under 2 MB.');const reader=new FileReader();reader.onload=()=>{current().photo=reader.result;save();toast('Photo saved. Save your profile to keep any text edits.');};reader.readAsDataURL(file);});
document.querySelector('#attraction-range')?.addEventListener('input',e=>{const value=Number(e.target.value);current().attraction[other().id]=value;save();document.querySelector('#rating-display').innerHTML=`${value}<span class="small muted"> / 10</span>`;});document.querySelector('#attraction-range')?.addEventListener('change',()=>render());
document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const key=b.dataset.answer;if(b.dataset.category!==undefined)current().answers[key]=b.dataset.category;else if(b.dataset.value==='clear')delete current().answers[key];else current().answers[key]=b.dataset.value==='true';save();const scroll=window.scrollY;render();window.scrollTo(0,scroll);});document.querySelectorAll('[data-scalar]').forEach(s=>s.onchange=()=>{if(s.value==='')delete current().answers[s.dataset.scalar];else current().answers[s.dataset.scalar]=Number(s.value);save();const scroll=window.scrollY;render();window.scrollTo(0,scroll);});}
function action(a){if(['simulate','profile','tree'].includes(a)){tab=a;render()}else if(a==='trace'){showTrace=true;tab='tree';mode='visual';render()}else if(a==='remove-photo'){delete current().photo;save();render()}else if(a==='clear-answers'){current().answers={};save();render();toast('Answers cleared. Unanswered questions now appear first.')}else if(['pass-attraction','like-attraction','clear-attraction'].includes(a)){if(a==='clear-attraction')delete current().attraction[other().id];else current().attraction[other().id]=a==='like-attraction'?8:3;save();render()}else if(a==='export'){const blob=new Blob([JSON.stringify(current().tree,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='cupid-tree.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
render();
